// ═══ POOL DEADLOCK: parent waits for child in same pool ═══
ExecutorService pool = Executors.newFixedThreadPool(4);  // 4 workers!

for (int i = 0; i < 4; i++) {  // submit 4 parent tasks
    pool.submit(() -> {
        // Parent submits child to SAME pool:
        Future<String> child = pool.submit(() -> "child result");
        // Parent BLOCKS waiting for child:
        return child.get();  // DEADLOCK! All 4 workers are parents waiting!
        // Child tasks: QUEUED but no worker available to run them!
    });
}
// All 4 workers: BLOCKED on child.get()
// 4 children: QUEUED in pool's queue
// Nobody to execute children → PERMANENT DEADLOCK!

// ═══ FIX 1: POOL SEGREGATION ═══
ExecutorService parentPool = Executors.newFixedThreadPool(4);
ExecutorService childPool = Executors.newFixedThreadPool(4);  // SEPARATE!

for (int i = 0; i < 4; i++) {
    parentPool.submit(() -> {
        Future<String> child = childPool.submit(() -> "child result");  // DIFFERENT pool!
        return child.get();  // parent blocks on parentPool worker
        // childPool workers are FREE to execute children → no deadlock!
    });
}

// ═══ FIX 2: VIRTUAL THREADS (Java 21) ═══
try (var pool = Executors.newVirtualThreadPerTaskExecutor()) {
    for (int i = 0; i < 10_000; i++) {  // 10K parents!
        pool.submit(() -> {
            Future<String> child = pool.submit(() -> "child result");
            return child.get();  // parent blocks BUT:
            // Virtual thread UNMOUNTS from carrier → carrier free!
            // Child virtual thread MOUNTS on freed carrier → executes!
            // No finite pool → no deadlock!
        });
    }
}
// 10K parents + 10K children = 20K virtual threads → all on ~4 carriers!
// Blocking is FREE for virtual threads!

// ═══ WHY IT HAPPENS ═══
// Parent: holds a worker thread (finite resource!)
// Parent: calls child.get() → BLOCKS (thread occupied but doing nothing!)
// If ALL workers are parents waiting → pool EXHAUSTED → children QUEUED forever!
// Classic resource exhaustion deadlock!

// ═══ GENERAL RULE ═══
// NEVER submit + join in the same bounded pool!
// Either: use separate pools (bulkhead)
// Or: use virtual threads (unbounded, blocking free)
// Or: use CompletableFuture chains (non-blocking: thenCompose instead of get!)
