// ─── File: src/test/java/com/bank/pooldeadlock/PoolDeadlockTest.java ───
package com.bank.pooldeadlock;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class PoolDeadlockTest {

    // ═══ DEADLOCK: parent + child same pool ═══
    @Test
    void samePool_deadlock() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(2);  // only 2 workers!
        AtomicInteger completed = new AtomicInteger(0);
        CountDownLatch done = new CountDownLatch(2);

        for (int i = 0; i < 2; i++) {
            pool.submit(() -> {
                try {
                    Future<String> child = pool.submit(() -> "child");  // SAME pool!
                    child.get(3, TimeUnit.SECONDS);  // timeout to avoid hanging test!
                    completed.incrementAndGet();
                } catch (TimeoutException e) {
                    // DEADLOCK detected via timeout! Children never execute!
                } catch (Exception e) { }
                done.countDown();
            });
        }

        done.await(10, TimeUnit.SECONDS);
        System.out.println("Completed: " + completed.get() + "/2");
        // Likely 0! Both parents blocked → children queued → timeout!
        pool.shutdownNow();
    }

    // ═══ FIX: separate pools ═══
    @Test
    void separatePools_noDeadlock() throws InterruptedException {
        ExecutorService parentPool = Executors.newFixedThreadPool(2);
        ExecutorService childPool = Executors.newFixedThreadPool(2);
        AtomicInteger completed = new AtomicInteger(0);
        CountDownLatch done = new CountDownLatch(2);

        for (int i = 0; i < 2; i++) {
            parentPool.submit(() -> {
                try {
                    Future<String> child = childPool.submit(() -> "child");  // DIFFERENT!
                    child.get(3, TimeUnit.SECONDS);
                    completed.incrementAndGet();
                } catch (Exception e) { }
                done.countDown();
            });
        }

        done.await(10, TimeUnit.SECONDS);
        assertThat(completed.get()).isEqualTo(2);  // both completed! No deadlock!
        parentPool.shutdown(); childPool.shutdown();
    }

    // ═══ FIX: CompletableFuture (non-blocking, no join!) ═══
    @Test
    void completableFuture_nonBlocking() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        AtomicInteger completed = new AtomicInteger(0);

        CompletableFuture<?>[] futures = new CompletableFuture[4];
        for (int i = 0; i < 4; i++) {
            futures[i] = CompletableFuture
                .supplyAsync(() -> "parent", pool)
                .thenApplyAsync(p -> p + "+child", pool);  // chained, not join!
                // No thread blocks waiting for child! Non-blocking pipeline!
        }
        CompletableFuture.allOf(futures).get(5, TimeUnit.SECONDS);
        // All complete! No deadlock! Threads freed between stages!
    }

    // ═══ FIX: Virtual threads (Java 21) ═══
    @Test
    void virtualThreads_noDeadlock() throws InterruptedException {
        try (var pool = Executors.newVirtualThreadPerTaskExecutor()) {
            AtomicInteger completed = new AtomicInteger(0);
            CountDownLatch done = new CountDownLatch(100);

            for (int i = 0; i < 100; i++) {
                pool.submit(() -> {
                    try {
                        Future<String> child = pool.submit(() -> "child");
                        child.get();  // blocks virtual thread, NOT carrier!
                        completed.incrementAndGet();
                    } catch (Exception e) { }
                    done.countDown();
                });
            }
            done.await(10, TimeUnit.SECONDS);
            assertThat(completed.get()).isEqualTo(100);  // ALL completed! No deadlock!
        }
    }
}
